package gt.com.ro.devumgapp.notificacion;
import android.app.Activity; import android.content.Intent; import android.view.*; import android.widget.TextView; import com.google.android.material.appbar.MaterialToolbar; import gt.com.ro.devumgapp.R; import gt.com.ro.devumgapp.core.network.RetrofitClient; import gt.com.ro.devumgapp.core.session.SessionManager; import gt.com.ro.devumgapp.notificacion.ui.NotificationInboxActivity; import retrofit2.*;
public final class NotificationBadge {private NotificationBadge(){} public static void attach(Activity a,MaterialToolbar toolbar){toolbar.setOnMenuItemClickListener(item->{if(item.getItemId()==R.id.action_notifications){a.startActivity(new Intent(a,NotificationInboxActivity.class));return true;}return false;});View action=toolbar.findViewById(R.id.action_notifications);if(action==null)return;action.setOnClickListener(v->a.startActivity(new Intent(a,NotificationInboxActivity.class)));refresh(toolbar);}
 public static void refresh(MaterialToolbar toolbar){if(!SessionManager.getInstance().isLoggedIn())return;View action=toolbar.findViewById(R.id.action_notifications);if(action==null)return;TextView badge=action.findViewById(R.id.notificationBadge);RetrofitClient.getClient().create(NotificationApi.class).count().enqueue(new Callback<NotificationModels.Count>(){public void onResponse(Call<NotificationModels.Count>c,Response<NotificationModels.Count>r){if(r.isSuccessful()&&r.body()!=null){long count=r.body().noLeidas;badge.setVisibility(count>0?View.VISIBLE:View.GONE);badge.setText(count>99?"99+":String.valueOf(count));}}public void onFailure(Call<NotificationModels.Count>c,Throwable t){}});}
}
